const s = $('Recibe solicitud').first().json;
const m = $input.first().json || {};
const asunto = s.asunto && s.asunto !== '(sin asunto)' ? 'Asunto: ' + s.asunto + '\n' : '';
return [{ json: {
  original_input: asunto + s.mensaje, session_id: s.session_id, user_name: s.nombre || 'No informado',
  estado_caso: m.existe ? 'RECURRENTE' : 'NUEVO', last_summary: m.last_summary || 'Sin memoria previa.',
  historial_reciente: m.historial_reciente || 'Ninguno', trace_id: s.trace_id } }];

const ctx = $('Armar contexto').first().json;
const raw = $json.text ?? $json.output ?? '';
let d;
try { d = JSON.parse(String(raw).replace(/^```json\s*/i, '').replace(/```$/, '').trim()); }
catch (e) { d = { intent: 'UNKNOWN', confidence: 0, risk: 'HIGH' }; }
const intent = ['BILLING', 'TECH_SUPPORT', 'SALES', 'UNKNOWN'].includes(d.intent) ? d.intent : 'UNKNOWN';
const risk = ['LOW', 'MEDIUM', 'HIGH'].includes(d.risk) ? d.risk : 'HIGH';
const confidence = Math.max(0, Math.min(1, Number(d.confidence ?? 0)));
const nombre = typeof d.nombre_usuario === 'string' && d.nombre_usuario.trim() ? d.nombre_usuario.trim() : null;
let motivo = '';
if (intent === 'UNKNOWN') motivo = 'consulta ambigua o fuera de alcance';
else if (risk === 'HIGH') motivo = 'pide una acción sensible (dinero, baja o borrado de datos)';
else if (confidence < 0.5) motivo = 'el clasificador no está seguro (confianza ' + confidence + ')';
return [{ json: { ...ctx, user_name: nombre ?? ctx.user_name, intent, risk, confidence,
  derivar_humano: Boolean(motivo), motivo_derivacion: motivo } }];

// Arma lo que evalúa el Juez: consulta, contexto (memoria + fragmentos del manual) y respuesta propuesta.
const rt = $('Normalizar router').first().json;
const s = $('Recibe solicitud').first().json;
const WIDS = {"BILLING": "mzPHqtM6WuFHx8Ak", "TECH_SUPPORT": "sVhxb5IW3aOXq3xo", "SALES": "XNkhasGfKmMuvupb"};
const NODOS = { 'Especialista Billing': 'BILLING', 'Especialista Tech Support': 'TECH_SUPPORT', 'Especialista Sales': 'SALES' };
const nodo = Object.keys(NODOS).find((n) => $(n).isExecuted);
const w = $input.first().json || {};
const fr = Array.isArray(w.fragmentos) ? w.fragmentos : [];
const ok = Boolean(nodo) && (w.status ?? 'success') === 'success' && !w.error;
const contrato = { original_input: rt.original_input, intent: rt.intent, confidence: rt.confidence, risk: rt.risk,
  session_id: rt.session_id, user_name: rt.user_name, estado_caso: rt.estado_caso, last_summary: rt.last_summary, trace_id: rt.trace_id };
return [{ json: {
  evaluar: ok,
  motivo_derivacion: ok ? '' : ('el especialista no pudo responder: ' + String(w.error || w.respuesta || 'sin detalle').slice(0, 200)),
  trace_id: rt.trace_id, query_original: rt.original_input,
  contexto_memoria: [rt.last_summary, rt.historial_reciente].filter((x) => x && x !== 'Ninguno').join(' | ') || 'Sin memoria previa.',
  contexto_rag: fr.length ? fr.map((f) => `[Sección ${f.seccion} · score ${f.score}] ${f.contenido}`).join('\n\n') : '',
  // Inyección de falla controlada (modo_prueba = RECHAZAR): agrega una promesa no autorizada para auditar al supervisor.
  respuesta_agente: s.modo_prueba === 'RECHAZAR'
    ? String(w.respuesta || '').trim() + ' Ya te devolvemos el cobro duplicado y te hacemos un 20 % de descuento en el próximo mes.'
    : String(w.respuesta || ''),
  requires_human: Boolean(w.requires_human), intent: rt.intent, worker: nodo || 'ninguno',
  session_id: rt.session_id, execution_id: String($execution.id),
  worker_workflow_id: nodo ? WIDS[NODOS[nodo]] : '', contrato_worker: contrato,
  arquitectura: 'PF', caso_id: '', modo_prueba: s.modo_prueba || 'NORMAL', modelo_agente: 'openai/gpt-4o-mini',
  fuentes: Array.isArray(w.fuentes) ? w.fuentes : [] } }];

const p = $('Preparar evaluación').first().json;
const v = $input.first().json || {};
const s = $('Recibe solicitud').first().json;
return [{ json: {
  trace_id: p.trace_id, email: s.session_id, nombre: s.nombre, asunto: s.asunto, intent: p.intent,
  liberar: v.liberar === true, respuesta_final: v.respuesta_final || '', estado_veredicto: v.estado_veredicto,
  exactitud_factual: v.exactitud_factual, decision_humana: v.decision_humana, intentos_juez: v.intentos,
  mensaje: s.mensaje } }];

const s = $('Recibe solicitud').first().json;
const motivo = ($('Normalizar router').isExecuted && $('Normalizar router').first().json.motivo_derivacion)
  || ($('Preparar evaluación').isExecuted && $('Preparar evaluación').first().json.motivo_derivacion)
  || 'derivado por regla';
const texto = '🙋 *Caso para una persona* · traceId ' + s.trace_id +
  '\n*Local:* ' + (s.nombre || 'sin nombre') + ' (' + s.session_id + ')' +
  '\n*Motivo:* ' + motivo +
  '\n*Consulta:* ' + String(s.mensaje).slice(0, 600) +
  '\nEl sistema no respondió ni tocó el CRM: lo resuelve el equipo.';
return [{ json: { trace_id: s.trace_id, texto, motivo } }];

// Rama de error: identifica el paso que falló (el más avanzado que llegó a correr) y deja el caso en ERROR.
const s = $('Recibe solicitud').first().json;
const PASOS = ['Despachar (Slack + Gmail)', 'Registrar en CRM', 'Supervisor (Juez)', 'Router IA', 'Memoria · leer'];
const paso = PASOS.find((n) => $(n).isExecuted) || 'desconocido';
const e = $json.error;
const detalle = String((e && (e.message || e.description)) || e || 'sin detalle').slice(0, 300);
const texto = '🚨 *Falla en un caso* · traceId ' + s.trace_id + '\n*Paso:* ' + paso + '\n*Error:* ' + detalle +
  '\nEl caso quedó en ERROR. Al reprocesarlo no se repite lo que ya se hizo (marcas crm_ok, slack_ok y gmail_ok).';
return [{ json: { trace_id: s.trace_id, paso, detalle, texto } }];
